insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (216, 'Little People, Big Dreams - Evonne Goolagong', 'Sanchez Vegara, Isabel', NULL, 'Meet Evonne Goolagong, the inspiring indigenous Australian tennis player. Evonne grew up on a hot, dusty farm in Australia. She was the third of eight children, and descendant of the Wirundjuri people, who have lived on the land for more than 60,000 years. Her talent for tennis was discovered at a local tennis club, and before she knew it, the girl dreaming about the place called "Wimbledon" was playing on center court. This moving book features stylish and quirky illustrations and extra facts at the back, including a biographical timeline with historical photos and a detailed profile of the brilliant tennis player''s life.', 'verified', '216_little_people_big_dreams_evonne_goolagong.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (217, 'Little People, Big Dreams - Vivienne Westwood', 'Sanchez Vegara, Isabel', NULL, 'Meet Vivienne Westwood, the flame-haired fashion designer and impresario. When Vivienne was a young woman, she wasn''t sure how a working class girl from England could make a living in the art world. But after discovering her passion for design and jewelry making, she erupted onto the fashion scene with a bang. Vivienne''s designs became iconic, and she became famous for letting her clothes speak for themselves. This moving book features stylish and quirky illustrations and extra facts at the back, including a biographical timeline with historical photos and a detailed profile of the designer''s life.', 'verified', '217_little_people_big_dreams_vivienne_westwood.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (218, 'Little People, Big Dreams - Frida Kahlo', 'Sanchez Vegara, Isabel', NULL, 'Meet Frida Kahlo, the world-renowned painter. When Frida was a teenager, a terrible road accident changed her life forever. Unable to walk, she began painting from her bed. Her self-portraits, which show her pain and grief, but also her passion for life and instinct for survival, have made her one of the most famous artists of the twentieth century. This moving book features stylish and quirky illustrations and extra facts at the back, including a biographical timeline with historical photos and a detailed profile of the artist''s life.', 'verified', '218_little_people_big_dreams_frida_kahlo.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (219, 'Little People, Big Dreams - Aretha Franklin', 'Sanchez Vegara, Isabel', NULL, 'Meet Aretha Franklin, "The Queen of Soul." The fourth of five children, Aretha was born in Tennessee and took the stage at an early age in her father''s church choir. She went on to become the best-selling rhythm and blues singer of all time, and the first woman to be installed in the Rock and Roll Hall of Fame. This moving book features stylish and quirky illustrations and extra facts at the back, including a biographical timeline with historical photos and a detailed profile of the broadcaster''s life.', 'verified', '219_little_people_big_dreams_aretha_franklin.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (220, 'Little People, Big Dreams - Marie Curie', 'Sanchez Vegara, Isabel', NULL, 'Meet Marie Curie, the Nobel Prize-winning scientist. When Marie was young, she was unable to go to college because she was a woman. But when she was older, her scientific work was respected around the world. Her discoveries of radium and polonium dramatically helped in the fight against cancer, and she went on to win the Nobel Prize for Physics! This moving book features stylish and quirky illustrations and extra facts at the back, including a biographical timeline with historical photos and a detailed profile of the scientist''s life.', 'verified', '220_little_people_big_dreams_marie_curie.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (221, 'Little People, Big Dreams - Audrey Hepburn', 'Sanchez Vegara, Isabel', NULL, 'Meet Audrey Hepburn, the iconic Hollywood movie star. Audrey Hepburn grew up in Arnhem in the Netherlands. After living through the hardships of World War Two, she moved to study ballet in London. She went on to star in plays and films, eventually becoming one of the most iconic actresses of all time. This moving book features stylish and quirky illustrations and extra facts at the back, including a biographical timeline with historical photos and a detailed profile of the actress''s life.', 'verified', '221_little_people_big_dreams_audrey_hepburn.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (222, 'Little People, Big Dreams - Stevie Wonder', 'Sanchez Vegara, Isabel', NULL, 'Meet Stevie Wonder, the genius behind some of the world''s best-loved songs. At just 8 years old, it was clear that Steveland Judkins was going to be a star. Renamed Stevie Wonder for his astonishing talent on the piano and other instruments, he wrote and performed some of the biggest hits of the 1970s. Stevie became known for his inventiveness, his soulful voice, and the social commentary in his lyrics. He is a UN Messenger of Peace and remains one of the music world''s most iconic figures. This inspiring book features stylish and quirky illustrations and extra facts at the back, including a biographical timeline with historical photos and a detailed profile of the great musician''s life.', 'verified', '222_little_people_big_dreams_stevie_wonder.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (223, 'Little People, Big Dreams - John Lennon', 'Sanchez Vegara, Isabel', NULL, 'Meet John Lennon, the boy from Liverpool who dreamed of peace. When John Lennon formed a band while still in school, he couldn''t have known they were about to change music forever. With their exciting new sounds, rebel attitudes and gift for songwriting, everyone went crazy for The Beatles. Today, John is remembered not just as a musical icon, but as a champion of world peace. This inspiring book features stylish and quirky illustrations and extra facts at the back, including a biographical timeline with historical photos and a detailed profile of the legendary Beatle''s life.', 'verified', '223_little_people_big_dreams_john_lennon.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (224, 'Little People, Big Dreams - Martin Luther King Jr', 'Sanchez Vegara, Isabel', NULL, 'Meet Martin Luther King Jr., the inspiring minister and civil rights activist. Little Martin grew up in a family of preachers: his dad was a preacher, his uncle was a preacher, his grandfather was a preacher…so maybe he''d become a great preacher too. One day, a friend invited him to play at his house. Martin was shocked when his mother wouldn''t let him in because he was black. That day he realized there was something terribly unfair going on. Martin believed that no one should remain silent and accept something if it''s wrong. And he promised himself that—when he grew up—he''d fight injustice with the most powerful weapon of all: words. This moving book features stylish and quirky illustrations and extra facts at the back, including a biographical timeline with historical photos and a detailed profile of the inspiring activist''s life.', 'verified', '224_little_people_big_dreams_martin_luther_king_jr.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (225, 'Little People, Big Dreams - Bob Dylan', 'Sanchez Vegara, Isabel', NULL, 'Meet Bob Dylan, the iconic singer-songwriter, poet, and artist. Bob Dylan was born in Duluth, Minnesota. As a teenager, he played in various bands and, over time, his interest in music deepened, with a particular passion for American folk music and blues. Dylan moved to New York City in 1961, where he began to perform poetry and music in clubs and cafés in Greenwich Village. There, he recorded a number of albums that made him one of the most influential musicians of history. This fascinating book features stylish and quirky illustrations and extra facts at the back, including a biographical timeline with historical photos and a detailed profile of the musician''s life.', 'verified', '225_little_people_big_dreams_bob_dylan.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (226, 'Little People, Big Dreams - Elton John', 'Sanchez Vegara, Isabel', NULL, 'Meet Elton John, the piano wizard who rocketed to stardom with his music. As a child, Elton started playing his grandmother''s piano in Harrow, London. He could pick tunes out by ear and was soon attending lessons at the Royal Academy. After answering an advertisement in a newspaper, Elton teamed up with a lyric-writing buddy: Bernie Taupin. The rest was history. Elton''s songwriting talent, musical skill, and dazzling outfits have made him one of the all-time greats. This moving book features stylish and quirky illustrations and extra facts at the back, including a biographical timeline with historical photos and a detailed profile of the musician''s life.', 'verified', '226_little_people_big_dreams_elton_john.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (227, 'Little People, Big Dreams - Prince', 'Sanchez Vegara, Isabel', NULL, 'Meet Prince, one of the most iconic performers in music history. From a young age, Prince was obsessed with music. Even though he couldn''t read it, his talent—whether on piano, drums, guitar, or vocals—turned him into an icon. Combining funk, disco, soul, and almost every other genre out there, his songs are some of the best-loved all around the world. Prince knew that he didn''t have to be like anyone else to be a star—and there was no one quite like Prince. This inspiring book features stylish and quirky illustrations and extra facts at the back, including a biographical timeline with historical photos and a detailed profile of the music legend''s life.', 'verified', '227_little_people_big_dreams_prince.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (228, 'Little People, Big Dreams - Jane Austen', 'Sanchez Vegara, Isabel', NULL, 'Meet Jane Austen, the great British novelist. Little Jane was born into a large family with seven brothers and sisters. She grew up reading and writing stories in the English countryside. As an adult, she wrote witty commentaries about landed gentry in a way that no one had ever done before, portraying young women who bravely made their own choices. These novels made Jane one of the most loved British writers of all time. This moving book features stylish and quirky illustrations and extra facts at the back, including a biographical timeline with historical images and a detailed profile of the author''s life.', 'verified', '228_little_people_big_dreams_jane_austen.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (229, 'Little People, Big Dreams - Coco Chanel', 'Sanchez Vegara, Isabel', NULL, 'Meet Coco Chanel, international style icon. Following the death of her mother, Coco spent her early life in an orphanage, where she was taught how to use a needle and thread. From there, she became a cabaret singer, seamstress, hat maker, and, eventually, the world''s most famous fashion designer. This moving book features stylish and quirky illustrations and extra facts at the back, including a biographical timeline with historical photos and a detailed profile of the designer''s life.', 'verified', '229_little_people_big_dreams_coco_chanel.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (230, 'Little People, Big Dreams - Stephen Hawking', 'Sanchez Vegara, Isabel', NULL, 'Meet Stephen Hawking, the genius physicist and author. When Stephen Hawking was a little boy, he used to stare up at the stars and wonder about the universe. Although he was never top of the class, his curiosity took him to the best universities in England: Oxford and Cambridge. It also led him to make one of the biggest scientific discoveries of the 20th century: Hawking radiation. This moving book features stylish and quirky illustrations and extra facts at the back, including a biographical timeline with historical photos and a detailed profile of the brilliant physicist''s life.', 'verified', '230_little_people_big_dreams_stephen_hawking.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (231, 'Our Dreaming', 'Saunders, Kirli', NULL, 'Goodjagah, little one, walk with me … I want to tell you our Dreaming as the Elders told it to me.

Award-winning storytellers, Gunai woman Kirli Saunders and Bigambul man Dub Leffler, explore a deep love and respect for Country and all her spirits … past, present and beyond.', 'verified', '231_our_dreaming.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (232, 'Dingo', 'Saxby, Claire', NULL, 'Poetic language and glorious illustrations follow a dingo from the comfort of her pack into the darkening landscape in search of food for her family. Can you see her? There — deep in the stretching shadows — a dingo. Her pointed ears twitch. Her tawny eyes flash in the low-slung sun. Dingo leaves her sleeping pups with her mate and lifts her head to smell the air. Dusk is a busy time — the time for hunting. Softly and fleetly she runs through the forest, past a possum, a wombat, and kangaroos in the gully below. Now she climbs to the highest point and sniffs again, locating the scent of rabbits in the wind. Interspersed with text offering facts for curious readers, Dingo is a lyrical foray into the life of these fascinating wild dogs.', 'verified', '232_dingo.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (233, 'Koala', 'Saxby, Claire', NULL, 'A fabulous addition to the award-winning narrative nonfiction Nature Storybook series, featuring the iconic Australian marsupial – the koala. It is time for Little Koala to leave the protection of his mother. But many challenges and dangers lie ahead for him as he searches for his own home eucalypt and learns to be independent. During his search he encounters other territorial koalas, wanders through a bushfire-ravaged landscape and endures a night of storms. Koala is written by award-winning nonfiction picture book specialist Claire Saxby, and illustrated by the much-celebrated Julie Vivas, one of Australia''s premier illustrators.', 'verified', '233_koala.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (234, 'Tasmanian Devil', 'Saxby, Claire', NULL, 'An engaging addition to the Nature Storybooks series, Tasmanian Devil showcases different elements of the habitat, behaviours, and day to day life of one of Australia''s most famous marsupials. Now in paperback. In Tasmanian Devil award-winning author Claire Saxby and talented artist Max Hamilton tell the story of two imps, or young devils. As the book progresses the brother and sister grow and venture further from the den, exploring more and more of their world in this stunning Nature Storybook.', 'verified', '234_tasmanian_devil.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (235, 'Kookaburra', 'Saxby, Claire', NULL, 'An exciting addition to the narrative nonfiction "Nature Storybooks" series, about kookaburras. In the crinkled shadows night-dwellers yawn, day-creatures stretch and Kookaburra laughs. Kook-kook-kook. Kak-kak-kak. The team behind Dingo is back again with a new addition to the "Nature Storybooks" series. The kookaburra, perhaps Australia''s best-loved bird, is shown in all her glory in a stunning and vivid landscape. Follow along as Kookaburra finds food for her young and goes searching for a nest with her mate.', 'verified', '235_kookaburra.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (236, 'Great White Shark', 'Saxby, Claire', NULL, 'Follow a female shark as she heads to warm waters for the sake of her young in a lyrical, fact-filled look at one of the ocean’s top predators. The great white shark swims on. Her tail sways from side to side; her fins keep her balanced. She travels the fast lane where she can, cruising invisible seaways. As she traverses her ocean home, the great white shark’s charcoal skin blends with the dark depths of the ocean, her white belly floating pale below. She carries seven pups in her belly, and her job is to give them the best possible chance at survival. Her journey will take her where she needs to go to stay nourished until she gives birth, far from shore. Set in a stunning underwater world, Claire Saxby''s signature poetic prose, offset by running facts, and Cindy Lane''s striking illustrations showcase the power and grace of one of the ocean’s most misunderstood creatures.', 'verified', '236_great_white_shark.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (237, 'Emu', 'Saxby, Claire', NULL, 'Did you know it’s the emu father who protects the chicks? Follow a doting dad as he keeps his brood safe—from when they’re granite-green eggs until they’re all grown up. In the open eucalyptus forest of Australia, an emu as tall as a human settles down on his nest to warm and protect the eggs left by his mate. When they hatch, the chicks will be ten times bigger than domestic chicken hatchlings and covered in chocolate-and-cream stripes to provide camouflage in the grasslands. This unusual family sticks together until the hatchlings grow up, facing dangers that include eagles and dingoes. Ornithologically inclined youngsters will delight in this visually striking chronicle full of fun emu facts.', 'verified', '237_emu.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (238, 'Iceberg', 'Saxby, Claire', NULL, 'An iceberg is born into spring and travels through the seasons before dying in a new spring. A stunning, lyrical story for our times, from renowned picture book creators Claire Saxby and Jess Racklyeft.

In the final freeze of an Antarctic winter, green tails wave across a star-full sky, as if to farewell endless nights. If this world looks empty, look closer...Penguins trek across the ice to their winter homes. As the temperature warms, birds fly above on their long migrations. And with the advent of summer, beneath an iceberg, the sea is teeming with life.

Ocean, sky, snow and ice - minute greens and giant blues - dance a delicate dance in this evocative portrayal of the life cycle of an iceberg.', 'verified', '238_iceberg.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (239, 'Big Red Kangaroo', 'Saxby, Claire', 'Graham Byrne', 'Follow a dominant male kangaroo as he leads his mob in search of food--and holds his own against other males who vie for his role. In the center of Australia, the sun is setting over the baked earth, and Red Kangaroo stirs from his rest. It''s breakfast time, and Red must lead his mob of kangaroos off to find grasses for grazing. But Red is also on the watch for young male kangaroos who are ready to challenge him and try to take his place as leader. Striking illustrations set the mood for a compelling, fact-filled story of red kangaroos in the wilds of Australia.', 'verified', '239_big_red_kangaroo.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (240, 'The Boy Who Loved Words', 'Schotter, Roni', 'Giselle Potter', 'Words. Selig collects them, ones that stir his heart (Mama!) and ones that make him laugh (giggle). But what to do with so many luscious words? After helping a poet find the perfect words for his poem (lozenge, lemon, and licorice), he figures it out: His purpose is to spread the word to others. And so he begins to sprinkle, disburse, and broadcast them to people in need. "From the Hardcover edition.', 'verified', '240_the_boy_who_loved_words.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (241, 'The True Story of the 3 Little Pigs', 'Scieszka, Jon', 'Lane Smith', 'You thought you knew the story of the "The Three Little Pigs"… You thought wrong.

In this hysterical and clever fracture fairy tale picture book that twists point of view and perspective, young readers will finally hear the other side of the story of "The Three Little Pigs."', 'verified', '241_the_true_story_of_the_3_little_pigs.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (242, 'The Giving Tree', 'Silverstein, Shel', NULL, 'A young boy grows to manhood and old age experiencing the love and generosity of a tree which gives to him without thought of return.', 'verified', '242_the_giving_tree.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (243, 'Runt', 'Silvey, Craig', NULL, 'A heart-warming, funny, beautifully told story for readers of all ages from the bestselling author of Jasper Jones and Honeybee.

''You don''t have to carry the weight of the world in your tool belt.''

Annie Shearer lives in the country town of Upson Downs with her best friend, an adopted stray dog called Runt. The two share a very special bond.

After years evading capture, Runt is remarkably fast and agile, perfect for herding runaway sheep. But when a greedy local landowner puts her family''s home at risk, Annie directs Runt''s extraordinary talents towards a different pursuit - winning the Agility Course Grand Championship at the lucrative Krumpets Dog Show in London.

However, there is a curious catch: Runt will only obey Annie''s commands if nobody else is watching.

With all eyes on them, Annie and Runt must beat the odds and the fastest dogs in the world to save her farm.

Runt is a heart-warming and hilarious tale of kindness, friendship, hurdles, hoops, tunnels, see-saws, being yourself and bringing out the best in others.', 'verified', '243_runt.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (244, 'We Are Australians', 'Smith, Duncan & Godwin, Nicole', NULL, 'For those born in Australia, it''s easy to take citizenship and its responsibilities for granted. But there is much more to being an Australian citizen than having a passport and the right to vote.', 'verified', '244_we_are_australians.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (245, 'Tiny Wonders', 'Soweol Han, Sally', NULL, 'April thinks if her town was a colour, it would be grey. Everyone is too busy to stop and look around. How can she help them slow down? When she remembers the happiness that dandelions brought her grandmother, April comes up with a plan... Bursting with colour, this is a sweet story about flowers, family and the wonders children wish for.', 'verified', '245_tiny_wonders.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (246, 'The All New Must Have Orange 430', 'Speechley, Michael', NULL, 'A cheeky picture book for anyone who''s bought a thingy or whatsit . . . and doesn''t quite know why. In his debut picture book, Michael Speechley explores our obsession with stuff in a fun and edifying way.', 'verified', '246_the_all_new_must_have_orange_430.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (247, 'Thankful', 'Spinelli, Eileen', NULL, 'A warm celebration of gratitude focusing on the many things, big and small, for which we can be thankful. This gentle narrative promotes appreciation and positive thinking about the blessings in our lives.', 'needs_review', '247_thankful.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (248, 'Someday', 'Spinelli, Eileen', NULL, 'A young girl contrasts the exciting things she might someday do, like digging for dinosaur bones and swimming with dolphins, with her present-day activities of finding loose change in the sofa cushions and feeding her goldfish.', 'verified', '248_someday.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (249, 'We Love You, Magoo', 'Stewart, Briony', NULL, 'Pitched perfectly at the preschooler, just learning the rules who loves being the boss. Gorgeous illustrations and a rhyming text that''s a delight to read out loud.', 'verified', '249_we_love_you_magoo.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (250, 'Tensy Farlow and the Home For the Mislaid Children', 'Storer, Jen', NULL, 'Dumped in the River Charon, hunted by an accursed river creature and betrayed by the wicked Matron Pluckrose, Tensy Farlow is in mortal danger. She has no parents. Worse still, she has no guardian angel. When she is thrown into the Home for Mislaid Children – a gloomy orphanage where ravens attack, Watchers hover over your bed, and even the angels cannot be trusted – it seems that all hope is lost. Yet could it be that a plucky, flame-haired orphan with a mysterious past is precisely what this dark world needs? ''deliciously menacing, deliciously funny . . . a glorious read'' AUSTRALIAN BOOKSELLERS'' ASSOCIATION', 'verified', '250_tensy_farlow_and_the_home_for_the_mislaid_children.jpg');
